$('savePurchase').onclick=async()=>{try{const r=await api('/purchases',{method:'POST',body:JSON.stringify({supplier_id:Number($('purchaseSupplier').value),items:[{product_id:Number($('purchaseProduct').value),quantity:Number($('purchaseQty').value),unit_cost:Number($('purchaseUnitCost').value)}],paid_amount:Number($('purchasePaid').value),note:$('purchaseNote').value})});$('purchaseMsg').textContent='خرید '+r.purchase_no+' ثبت شد.';await refresh();await loadFinance()}catch(e){$('purchaseMsg').textContent=e.message}};
